  1→//! Project type detection.
  2→
  3→use std::path::Path;
  4→
  5→use super::file_detection::{any_file_exists, file_exists};
  6→use super::types::DetectionResult;
  7→
  8→/// Detected project type.
  9→#[derive(Debug, Clone, PartialEq)]
 10→pub enum ProjectType {
 11→    Ruby,
 12→    Node,
 13→    Python,
 14→    Rust,
 15→    Go,
 16→    Swift,
 17→    Unknown,
 18→}
 19→
 20→/// Result of project detection.
 21→#[derive(Debug, Clone)]
 22→pub struct ProjectDetection {
 23→    pub primary_type: ProjectType,
 24→    pub all_types: Vec<ProjectType>,
 25→    pub details: Vec<DetectionResult>,
 26→}
 27→
 28→/// Detects project types based on marker files.
 29→pub struct ProjectDetector;
 30→
 31→impl ProjectDetector {
 32→    /// Detect all project types in a directory.
 33→    pub fn detect(project_root: &Path) -> ProjectDetection {
 34→        let mut all_types = Vec::new();
 35→        let mut details = Vec::new();
 36→
 37→        // Ruby
 38→        if file_exists(project_root, "Gemfile") {
 39→            all_types.push(ProjectType::Ruby);
 40→            details.push(
 41→                DetectionResult::found("Ruby")
 42→                    .with_detail("Gemfile found")
 43→                    .with_template("bundler"),
 44→            );
 45→        }
 46→
 47→        // Node
 48→        if file_exists(project_root, "package.json") {
 49→            all_types.push(ProjectType::Node);
 50→
 51→            let lockfile = any_file_exists(
 52→                project_root,
 53→                &[
 54→                    "yarn.lock",
 55→                    "package-lock.json",
 56→                    "pnpm-lock.yaml",
 57→                    "bun.lockb",
 58→                ],
 59→            );
 60→
 61→            let template = match lockfile.as_deref() {
 62→                Some("yarn.lock") => "yarn",
 63→                Some("pnpm-lock.yaml") => "pnpm",
 64→                Some("bun.lockb") => "bun",
 65→                _ => "npm",
 66→            };
 67→
 68→            details.push(
 69→                DetectionResult::found("Node.js")
 70→                    .with_detail("package.json found")
 71→                    .with_template(template),
 72→            );
 73→        }
 74→
 75→        // Python
 76→        if file_exists(project_root, "pyproject.toml")
 77→            || file_exists(project_root, "requirements.txt")
 78→            || file_exists(project_root, "setup.py")
 79→        {
 80→            all_types.push(ProjectType::Python);
 81→
 82→            let template = if file_exists(project_root, "poetry.lock") {
 83→                "poetry"
 84→            } else if file_exists(project_root, "uv.lock") {
 85→                "uv"
 86→            } else {
 87→                "pip"
 88→            };
 89→
 90→            details.push(
 91→                DetectionResult::found("Python")
