            .messages()
            .iter()
            .any(|m| m.contains("Requires: ruby, bundler")));
    }

    #[test]
    fn dry_run_with_ui_shows_sensitive_placeholder() {
        let temp = TempDir::new().unwrap();

        let config: BivvyConfig = serde_yaml::from_str(
            r#"
            workflows:
              default:
                steps: [secret]
        "#,
        )
        .unwrap();

        let mut step = make_step("secret", "vault read secret/key", vec![]);
        step.sensitive = true;

        let mut steps = HashMap::new();
        steps.insert("secret".to_string(), step);

        let runner = WorkflowRunner::new(&config, steps);
        let options = RunOptions {
            dry_run: true,
            ..Default::default()
        };
        let ctx = InterpolationContext::new();
        let mut ui = MockUI::new();
        ui.set_interactive(true);

        runner
            .run_with_ui(
                &options,
                &ctx,
                &HashMap::new(),
                temp.path(),
                false,
                &HashMap::new(),
                None,
                &mut ui,
            )
            .unwrap();

        // Sensitive steps should not reveal the command
        assert!(
            !ui.messages().iter().any(|m| m.contains("vault")),
            "dry-run should hide sensitive commands"
        );
        assert!(
            ui.messages().iter().any(|m| m.contains("SENSITIVE")),
            "dry-run should show sensitive placeholder"
        );
    }
}

