        "#,
        )
        .unwrap();

        let mut steps = HashMap::new();
        steps.insert(
            "failing".to_string(),
            make_step("failing", "exit 1", vec![]),
        );
        // next depends on failing to ensure deterministic ordering
        steps.insert(
            "next".to_string(),
            make_step(
                "next",
                &format!("touch {}", marker.display()),
                vec!["failing".to_string()],
            ),
